import{_ as e,c as t,o as r,a2 as a}from"./chunks/framework.DdOM6S6U.js";const h=JSON.parse('{"title":"Parent segments & URL routes","description":"","frontmatter":{"sidebarPos":3,"sidebarTitle":"Parent segments & URL routes","sidebarGroupTitle":"Cms","outline":"deep"},"headers":[],"relativePath":"guide/cms/parent-segments-and-url-routes.md","filePath":"guide/cms/parent-segments-and-url-routes.md","lastUpdated":1784841066000}'),o={name:"guide/cms/parent-segments-and-url-routes.md"},s=a('<h1 id="parent-segments-url-routes" tabindex="-1">Parent segments &amp; URL routes <a class="header-anchor" href="#parent-segments-url-routes" aria-label="Permalink to &quot;Parent segments &amp; URL routes&quot;">​</a></h1><p>Public URLs are data, not one Laravel route per page.</p><h2 id="parentsegment" tabindex="-1">ParentSegment <a class="header-anchor" href="#parentsegment" aria-label="Permalink to &quot;ParentSegment&quot;">​</a></h2><p>One row per <strong>target model class + locale</strong>: the shared path prefix for that type (e.g. <code>pages</code>, or empty for locale root).</p><ul><li>Table / entity: <code>ParentSegment</code></li><li>Config: <code>modularous.cms_parent_segments</code></li><li>Models opt in with <code>HasParentSegment</code> (bundled on <code>IsCmr</code>)</li></ul><p>Changing a prefix can resync UrlRoute rows for that model class (<code>cms_routing.resync_registry_after_parent_segments_change</code>).</p><h2 id="urlroute" tabindex="-1">UrlRoute <a class="header-anchor" href="#urlroute" aria-label="Permalink to &quot;UrlRoute&quot;">​</a></h2><p>Flat registry of published paths:</p><table><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>locale</code></td><td>Locale code</td></tr><tr><td><code>normalized_path</code></td><td>Path without leading slash</td></tr><tr><td><code>urlable</code></td><td>Morph to Page (or other CMR) / Redirect</td></tr><tr><td><code>kind</code></td><td><code>page_public</code> or <code>redirect_source</code></td></tr></tbody></table><p>Synced on entity save via <code>CmsUrlRouteRegistry</code> (prefix + slug leaf, or singular prefix-only paths).</p><h2 id="public-resolve" tabindex="-1">Public resolve <a class="header-anchor" href="#public-resolve" aria-label="Permalink to &quot;Public resolve&quot;">​</a></h2><ol><li>Catch-all receives the request (<a href="./public-routing">Public routing</a>).</li><li><code>CmsVisitorRedirectResolver</code> derives locale + inner path.</li><li><code>CmsPublicModelResolver</code> finds a <code>page_public</code> UrlRoute (with slugless / implicit-locale rules).</li><li>ParentSegment registry gate must allow the model class.</li><li>Controller renders presentation (<a href="./page-layouts">Page layouts</a>).</li></ol><p>Universal mode (<code>cms_routing.universal_cms_public_front</code>, default true): one <code>CmsPublicFrontController</code> for all ParentSegment targets. Legacy mode registers per-module catch-alls when that flag is false.</p><h2 id="config" tabindex="-1">Config <a class="header-anchor" href="#config" aria-label="Permalink to &quot;Config&quot;">​</a></h2><p>Primary: <code>modularous.cms_routing</code>, <code>modularous.cms_parent_segments</code>. See <a href="./configuration">Configuration</a>.</p>',15),l=[s];function n(d,i,c,u,p,m){return r(),t("div",null,l)}const _=e(o,[["render",n]]);export{h as __pageData,_ as default};
